<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { consultarRecorrido, listarUnidadesGps } from '../services/recorridos'
import type { PuntoRecorrido, RecorridoResponse, UnidadGps } from '../interfaces/recorridos.interface'
const units=ref<UnidadGps[]>([]),selectedUnit=ref<number|null>(null),result=ref<RecorridoResponse|null>(null),selectedPoint=ref<PuntoRecorrido|null>(null),loading=ref(false),error=ref(''),summary=reactive({actualizadas:0,sin_ubicacion:0})
const filters=reactive({fecha:new Date().toISOString().slice(0,10),desde:'08:00',hasta:'18:00',modoVisualizacion:'ruta' as 'puntos'|'ruta'})
const coordinates=computed(()=>result.value?.segmentos.flat().length?result.value.segmentos.flat():result.value?.puntos??[])
const bounds=computed(()=>{const pts=coordinates.value;if(!pts.length)return{minLat:-13,maxLat:-12,minLng:-77,maxLng:-76};const lats=pts.map(p=>Number(p.latitud)),lngs=pts.map(p=>Number(p.longitud));let minLat=Math.min(...lats),maxLat=Math.max(...lats),minLng=Math.min(...lngs),maxLng=Math.max(...lngs);const latPad=Math.max((maxLat-minLat)*.15,.001),lngPad=Math.max((maxLng-minLng)*.15,.001);return{minLat:minLat-latPad,maxLat:maxLat+latPad,minLng:minLng-lngPad,maxLng:maxLng+lngPad}})
function x(lng:number){const b=bounds.value;return((lng-b.minLng)/(b.maxLng-b.minLng))*1000}function y(lat:number){const b=bounds.value;return 600-((lat-b.minLat)/(b.maxLat-b.minLat))*600}function line(points:{latitud:number;longitud:number}[]){return points.map(p=>`${x(Number(p.longitud))},${y(Number(p.latitud))}`).join(' ')}
async function initial(){loading.value=true;try{const r=await listarUnidadesGps();units.value=r.unidades;summary.actualizadas=r.actualizadas;summary.sin_ubicacion=r.sin_ubicacion}catch(e){error.value=message(e)}finally{loading.value=false}}
async function search(){if(!selectedUnit.value){error.value='Seleccione una unidad con GPS.';return}if(!filters.fecha||!filters.desde||!filters.hasta||filters.hasta<=filters.desde){error.value='Complete un intervalo horario válido.';return}loading.value=true;error.value='';selectedPoint.value=null;try{result.value=await consultarRecorrido({cisterna_id:selectedUnit.value,...filters})}catch(e){error.value=message(e)}finally{loading.value=false}}
function chooseUnit(unit:UnidadGps){selectedUnit.value=unit.id;result.value=null;selectedPoint.value=null}const battery=(level:number|null)=>level?`${level*20}%`:'—';const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo consultar el recorrido.'
onMounted(initial)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Gestión de Cisternas / Recorridos</nav><header class="hero"><div class="mark">GPS</div><div><small>DANA · GESTIÓN DE CISTERNAS</small><h1>Recorridos GPS</h1><p>Consulta la ubicación actual y el historial de desplazamiento de las unidades.</p></div><button @click="initial">↻ Actualizar unidades</button></header><p v-if="error" class="flash">{{error}}</p><section class="summary"><article><small>UNIDADES CON GPS</small><b>{{units.length}}</b></article><article><small>CON UBICACIÓN</small><b>{{summary.actualizadas}}</b></article><article><small>SIN UBICACIÓN</small><b>{{summary.sin_ubicacion}}</b></article><article><small>PUNTOS DEL RECORRIDO</small><b>{{result?.count??0}}</b><span>{{result?`${result.total_km} km estimados`:'Sin consulta'}}</span></article></section><section class="layout"><aside><header><small>UNIDADES MONITOREADAS</small><h2>Seleccione una cisterna</h2></header><div v-if="!units.length" class="aside-empty">No hay unidades GPS disponibles.</div><button v-for="unit in units" :key="unit.id" :class="{active:selectedUnit===unit.id}" @click="chooseUnit(unit)"><span class="truck">▰</span><span><b>{{unit.placa}}</b><small>{{unit.conductor||'Sin conductor'}}</small></span><i :class="{online:unit.latitud!==null}">{{unit.latitud!==null?'Ubicada':'Sin señal'}}</i></button></aside><main><form class="filters" @submit.prevent="search"><label>Fecha<input v-model="filters.fecha" type="date"></label><label>Desde<input v-model="filters.desde" type="time"></label><label>Hasta<input v-model="filters.hasta" type="time"></label><label>Visualización<select v-model="filters.modoVisualizacion"><option value="ruta">Ruta</option><option value="puntos">Puntos GPS</option></select></label><button>Consultar</button></form><div v-if="loading" class="empty">Consultando información GPS…</div><div v-else-if="!result" class="empty">Seleccione una unidad y un intervalo para visualizar su recorrido.</div><div v-else-if="!result.count" class="empty">No se encontraron ubicaciones en el intervalo seleccionado.</div><div v-else class="map"><svg viewBox="0 0 1000 600" preserveAspectRatio="xMidYMid meet"><defs><pattern id="gpsGrid" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M 50 0 L 0 0 0 50" fill="none" stroke="#dfe8e9"/></pattern></defs><rect width="1000" height="600" fill="#f4f8f7"/><rect width="1000" height="600" fill="url(#gpsGrid)"/><template v-if="filters.modoVisualizacion==='ruta'"><polyline v-for="(segment,index) in result.segmentos" :key="index" :points="line(segment)" fill="none" stroke="#765bd1" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/></template><g v-for="(point,index) in result.puntos" :key="index" :transform="`translate(${x(Number(point.longitud))} ${y(Number(point.latitud))})`" class="point" @click="selectedPoint=point"><circle :r="point.estado==='INTERMEDIO'?7:13" :fill="point.estado==='INICIO'?'#2780bd':point.estado==='FIN'?'#d9565c':'#765bd1'" stroke="#fff" stroke-width="4"/></g></svg><div class="distance">{{result.total_km}} km · {{result.count}} puntos</div></div></main><aside class="detail"><header><small>DETALLE GPS</small><h2>{{selectedPoint?'Punto seleccionado':result?.unidad.placa||'Sin recorrido'}}</h2></header><template v-if="result"><div class="plate">{{result.unidad.placa}}</div><dl><div><dt>Conductor</dt><dd>{{result.unidad.conductor||'—'}}</dd></div><div><dt>Capacidad</dt><dd>{{result.unidad.capacidad}} m³</dd></div><div><dt>Celular</dt><dd>{{result.unidad.celular||'—'}}</dd></div><template v-if="selectedPoint"><div><dt>Estado</dt><dd>{{selectedPoint.estado}}</dd></div><div><dt>Fecha y hora</dt><dd>{{selectedPoint.fechahora}}</dd></div><div><dt>Velocidad</dt><dd>{{selectedPoint.velocidad??'—'}} km/h</dd></div><div><dt>Batería GPS</dt><dd>{{battery(selectedPoint.bateria)}}</dd></div><div><dt>Coordenadas</dt><dd>{{Number(selectedPoint.latitud).toFixed(6)}}, {{Number(selectedPoint.longitud).toFixed(6)}}</dd></div></template></dl></template><div v-else class="aside-empty">Consulta un recorrido para ver sus detalles.</div></aside></section></div></template>
